def f(grid):
    h, w = len(grid), len(grid[0])
    result = [row[:] for row in grid]  # copy

    # Find all unique non-zero values and their occurrences
    val_sets = {}
    for i in range(h):
        for j in range(w):
            v = grid[i][j]
            if v != 0:
                if v not in val_sets:
                    val_sets[v] = set()
                val_sets[v].add((i, j))

    # For each value, analyze the runs
    for v in val_sets:
        runs = []
        for i in range(h):
            row_runs = []
            j = 0
            while j < w:
                if grid[i][j] == v:
                    start, end = j, j
                    while end < w and grid[i][end] == v:
                        end += 1
                    row_runs.append((start, end-start))
                    j = end
                else:
                    j += 1
            if row_runs:
                runs.append((i, row_runs))

        print(f"\nValue {v}:")
        for r_idx, (row_i, rr) in enumerate(runs):
            print(f"  Row {row_i}: {rr}")

        # Apply transformation logic

        # Topmost row gets special treatment
        if runs:
            top_row_idx = runs[0][0]
            top_run = runs[0][1][0]  # get first run from the list of runs

            # Check if top row is already full-width
            is_full_width = top_run[1] == w

            # Transform the top row
            if not is_full_width:
                # Fill row with doubled value
                new_val = v * 2
                result[top_row_idx] = [new_val] * w
                print(f"Top row {top_row_idx} becomes full of {new_val}")

            # For other rows with this value, adjust their runs
            for r_idx, (row_i, rr) in enumerate(runs[1:], 1):
                orig_start, orig_len = rr[0]

                # Calculate delta from top row's run start
                delta_col = top_run[0] - orig_start

                # New start and length: shift left by delta, length becomes same as top row's run
                new_start = orig_start + delta_col
                new_len = top_run[1]  # match top row's run length

                if new_start >= 0:
                    # Set cells to value
                    for c in range(new_start, min(new_start + new_len, w)):
                        result[row_i][c] = v
                    print(f"Row {row_i}: orig({orig_start},{orig_len}) -> new({new_start},{new_len})")

            # Add "echo" rows below - one row after the last one with this value
            if len(runs) > 1:
                last_row_with_val = runs[-1][0]
                orig_start_last = runs[-1][1][0]
                echo_row_idx = last_row_with_val + 1

                if echo_row_idx < h:
                    # Add single cell at original starting column of the last row
                    if 0 <= orig_start_last < w:
                        result[echo_row_idx][orig_start_last] = v
                        print(f"Echo row {echo_row_idx}: added at col {orig_start_last}")

        # Also check for echo after second-to-last row if there are more than 2 runs
        if len(runs) >= 2:
            for r_idx, (row_i, rr) in enumerate(runs[:-1]):
                orig_start, orig_len = rr[0]
                echo_row_idx = row_i + 1

                if echo_row_idx < h and echo_row_idx != last_row_with_val + 1:
                    # Only if this row doesn't already have something
                    if all(result[echo_row_idx][c] == 0 or result[echo_row_idx][c] != v for c in range(w)):
                        if all(grid[r][c] == 0 or grid[r][c] != v for r in range(echo_row_idx+1, min(echo_row_idx+h//2, h))):
                            # No existing value in those future rows
                            pass

            # Actually simpler: just add echo at every intermediate position
            # but only once per unique starting column pattern
            pass

    return result

