    full_rows_by_val = {}
    for i in range(h):
        vals = set(grid[i])
        if len(vals) == 1 and next(iter(vals)) != 0:
            v = list(vals)[0]
            full_rows_by_val[v] = full_rows_by_val.get(v, set()) | {i}

    full_row_mask = [False] * h
    for v, row_idxs in full_rows_by_val.items():
        for r_idx in row_idxs:
            full_row_mask[r_idx] = True

    # Helper to get runs of value v in row i
    def get_runs(row_i, v):
        runs = []
        j = 0
        while j < w:
            if grid[row_i][j] == v:
                start, end = j, j
                while end < w and grid[row_i][end] == v:
                    end += 1
                runs.append((start, end-start))
                j = end
            else:
                j += 1
        return runs

    # Track which cells have been modified for each value
    modified_cells = {v: set() for v in val_sets}

    for v in sorted(val_sets.keys()):
        # Get all rows with value v that are NOT full rows
        rows_with_v = [r for r in range(h) if v in grid[r] and not full_row_mask[r]]

        if not rows_with_v:
            continue

        print(f"\nProcessing value {v}:")
        print(f"  Non-full rows: {rows_with_v}")

        # Group into connected components (consecutive rows)
        components = []
        curr_comp = [rows_with_v[0]]
        for r_idx in rows_with_v[1:]:
            if r_idx == curr_comp[-1] + 1:
                curr_comp.append(r_idx)
            else:
                components.append(curr_comp)
                curr_comp = [r_idx]
        components.append(curr_comp)

        for comp in components:
            comp_runs = []
            for r_idx in comp:
                rr = get_runs(r_idx, v)
                if rr:
                    comp_runs.append((r_idx, rr))

            print(f"  Component rows: {[c[0] for c in comp_runs]}")

            if comp_runs:
                top_row_idx = comp_runs[0][0]
                top_run = comp_runs[0][1][0]

                # Transform top row - fill entire row with doubled value
                if top_run[1] < w:  # Not already full-width
                    new_val = v * 2
                    for c in range(w):
                        result[top_row_idx][c] = new_val
                        modified_cells[v].add((top_row_idx, c))
                    print(f"  Top row {top_row_idx} -> full {new_val}")

                ref_start = top_run[0]
                ref_len = top_run[1]

                # Process other rows in component
                for r_idx, rr in comp_runs[1:]:
                    orig_start, orig_len = rr[0]
                    delta_col = ref_start - orig_start
                    new_start = orig_start + delta_col
                    new_len = ref_len

                    if new_start >= 0:
                        for c in range(new_start, min(new_start + new_len, w)):
                            result[r_idx][c] = v
                            modified_cells[v].add((r_idx, c))
                        print(f"  Row {r_idx}: ({orig_start},{orig_len}) -> ({new_start},{new_len})")

                # Add echo below last row of component
                if len(comp_runs) > 1:
                    last_r_idx = comp_runs[-1][0]
                    last_start, last_len = comp_runs[-1][1][0]
                    orig_start_last = last_start
                    echo_row_idx = last_r_idx + 1

                    if echo_row_idx < h:
                        if 0 <= orig_start_last < w:
                            # Only add if this cell hasn't been modified by another component of same value
                            if (echo_row_idx, orig_start_last) not in modified_cells[v]:
                                result[echo_row_idx][orig_start_last] = v
                                modified_cells[v].add((echo_row_idx, orig_start_last))
                            print(f"  Echo at ({echo_row_idx},{orig_start_last})")
                    else:
                        print(f"  No space for echo (row {echo_row_idx} out of bounds)")

    return result

