# Actually let me rewrite cleanly
def f_clean(grid):
    h, w = len(grid), len(grid[0])
    result = [row[:] for row in grid]  # copy

    # Identify full rows and their values
    full_row_mask = []
    for i in range(h):
        vals = set(grid[i])
        is_full = len(vals) == 1 and next(iter(vals)) != 0
        full_row_mask.append(is_full)

    # Find values that appear ONLY in full rows
    values_only_in_full = set()
    for i in range(h):
        if full_row_mask[i]:
            v = list(set(grid[i]))[0]
            values_only_in_full.add(v)

    def get_runs(row_i, v):
        runs = []
        j = 0
        while j < w:
            if grid[row_i][j] == v:
                start, end = j, j
                while end < w and grid[row_i][end] == v:
                    end += 1
                runs.append((start, end-start))
                j = end
            else:
                j += 1
        return runs

    # Get all non-zero values
    all_vals = set()
    for i in range(h):
        for j in range(w):
            if grid[i][j] != 0:
                all_vals.add(grid[i][j])

    # Process values that are NOT only-in-full (these form structures)
    for v in sorted(all_vals - values_only_in_full):
        rows_with_v = [r for r in range(h) if not full_row_mask[r] and v in grid[r]]

        if not rows_with_v:
            continue

        print(f"\nProcessing value {v} at rows {rows_with_v}:")
        components = []
        curr_comp = [rows_with_v[0]]
        for r_idx in rows_with_v[1:]:
            if r_idx == curr_comp[-1] + 1:
                curr_comp.append(r_idx)
            else:
                components.append(curr_comp)
                curr_comp = [r_idx]
        components.append(curr_comp)

        for comp in components:
            comp_runs = []
            for r_idx in comp:
                rr = get_runs(r_idx, v)
                if rr:
                    comp_runs.append((r_idx, rr))

            if comp_runs:
                top_row_idx = comp_runs[0][0]
                top_run = comp_runs[0][1][0]

                new_val = v * 2
                for c in range(w):
                    result[top_row_idx][c] = new_val

                ref_start = top_run[0]
                ref_len = top_run[1]

                for r_idx, rr in comp_runs[1:]:
                    orig_start, orig_len = rr[0]

                    new_start = ref_start
                    new_len = ref_len

                    for c in range(new_start, min(new_start + new_len, w)):
                        result[r_idx][c] = v

                if len(comp_runs) > 1:
                    last_r_idx = comp_runs[-1][0]
                    last_pos_from_orig = comp_runs[-1][1][0][0]
                    echo_row_idx = last_r_idx + 1

                    if echo_row_idx < h and not full_row_mask[echo_row_idx]:
                        if 0 <= last_pos_from_orig < w:
                            result[echo_row_idx][last_pos_from_orig] = v

    return result

